window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"_NZUkod7lUM","speaker":"Kyriakos Mitsotakis","role":"Prime Minister","country":"Greece","region":"Europe","url":"https://www.youtube.com/watch?v=_NZUkod7lUM","date":"20260925","title":"🇬🇷 Greece - Prime Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1327,"words":2861,"counts":{"claims":43,"promises":5,"attacks":1},"topics":[{"topic":"AI regulation","share":0.195,"seconds":259},{"topic":"Greece economy","share":0.104,"seconds":138},{"topic":"Energy security","share":0.1012,"seconds":134},{"topic":"Cyprus reunification","share":0.0985,"seconds":131},{"topic":"UN Security Council","share":0.0566,"seconds":75},{"topic":"Syria stability","share":0.0554,"seconds":74},{"topic":"Greece-Turkey relations","share":0.0538,"seconds":71},{"topic":"UN multilateralism","share":0.0504,"seconds":67},{"topic":"Lebanon security","share":0.0493,"seconds":65},{"topic":"Greece presidency","share":0.0481,"seconds":64},{"topic":"Maritime security","share":0.048,"seconds":64},{"topic":"Gaza conflict","share":0.0473,"seconds":63},{"topic":"Sudan conflict","share":0.0466,"seconds":62},{"topic":"Migration policy","share":0.0459,"seconds":61}],"timeline":[[2,77,"UN Security Council"],[78,145,"UN multilateralism"],[146,209,"Maritime security"],[210,274,"Greece presidency"],[275,338,"Gaza conflict"],[339,404,"Lebanon security"],[406,479,"Syria stability"],[481,552,"Greece-Turkey relations"],[554,620,"Cyprus reunification"],[622,686,"Cyprus reunification"],[686,748,"Sudan conflict"],[749,810,"Migration policy"],[812,876,"Greece economy"],[877,951,"Greece economy"],[953,1022,"Energy security"],[1023,1088,"Energy security"],[1090,1152,"AI regulation"],[1153,1226,"AI regulation"],[1227,1289,"AI regulation"],[1290,1352,"AI regulation"],[1353,1366,null]],"stances":{"UN Security Council":"Kyriakos Mitsotakis states that Greece is concluding its second year on the UN Security Council and preparing to assume its presidency next month, while noting the urgent need to reinvigorate the UN amidst perilous times.","UN multilateralism":"Kyriakos Mitsotakis argues that international stability is eroding and calls for acknowledging the UN's successes, specifically citing the Law of the Sea Convention, to restore confidence in multilateralism.","Maritime security":"Kyriakos Mitsotakis argues that freedom of navigation must be championed globally and that Greece actively contributes to maritime security through the EU operation in the Red Sea.","Greece presidency":"Kyriakos Mitsotakis states that Greece will prioritize emerging technologies during its upcoming Security Council presidency and positions the country as a stable bridge between Europe and the East/South.","Gaza conflict":"Kyriakos Mitsotakis calls for the effective implementation of the Gaza peace plan, demands Hamas surrender its arms and have no role in Gaza's future, supports Palestinian ownership of reconstruction, advocates for a two-state solution, and expresses concern over illegal actions in the West Bank while highlighting Greece's strategic partnership with Israel.","Lebanon security":"Kyriakos Mitsotakis supports a sovereign and united Lebanon, endorses US-facilitated negotiations with Israel, and commits to continued assistance for the Lebanese armed forces while emphasizing the need for joint action regarding UNIFIL.","Syria stability":"Kyriakos Mitsotakis states that lasting stability in the Middle East requires a stable, inclusive Syria free from foreign interference and notes that while new authorities have taken steps, further progress is needed to protect religious minorities.","Greece-Turkey relations":"Kyriakos Mitsotakis emphasizes the need to improve relations with Turkey through open communication and adherence to international law, specifically citing the UN Convention on the Law of the Sea as the framework for resolving disputes.","Cyprus reunification":"Kyriakos Mitsotakis asserts that Turkey's continued occupation of Cyprus is a flagrant violation of international law and a test of the UN's credibility.","Sudan conflict":"Kyriakos Mitsotakis calls for an end to foreign interference and a Sudanese-led political process to resolve the humanitarian catastrophe.","Migration policy":"Kyriakos Mitsotakis argues that the European Union should actively use its capabilities to end the war and prevent a new wave of migration, while presenting Greece as a successful example of reform.","Greece economy":"Kyriakos Mitsotakis states that Greece has recovered from a severe economic crisis, achieving growth above the European average, solid public finances, declining debt, and improved investor trust through structural reforms.","Energy security":"Kyriakos Mitsotakis states that Greece will prioritize enhancing European competitiveness and security through new energy infrastructure projects during its upcoming EU Council presidency.","AI regulation":"Kyriakos Mitsotakis states that while AI has positive potential, the risks of unchecked and unregulated advancement currently outweigh the benefits."},"claims":[{"t":49,"quote":"Greece reaches the end of our second year on the UN Security Council and is again preparing to assume its presidency next month.","topic":"UN Security Council","kind":"fact"},{"t":60,"quote":"12 months ago, as we marked the 80th anniversary of the United Nations, we spoke of the need to reinvigorate","topic":"UN Security Council","kind":"fact"},{"t":102,"quote":"Secretary General Antonio Gutierrez has steered these United Nations through this exceptionally turbulent decade with a steadfast commitment to its charter and the values it embodies.","topic":"UN multilateralism","kind":"fact"},{"t":139,"quote":"the United Nations Convention on the Law of the Sea with 172 parties","topic":"UN multilateralism","kind":"number"},{"t":146,"quote":"UNLO provides the binding legal framework within which disputes can be managed peacefully rather than through force.","topic":"Maritime security","kind":"fact"},{"t":166,"quote":"Commercial vessels are being targeted and vital trade routes are used as instruments of pressure with grave consequences for supply chains, for energy markets, and for food security worldwide.","topic":"Maritime security","kind":"fact"},{"t":202,"quote":"Greece actively contributes to maritime security through the operation of the European Union diaspidas in the Red Sea.","topic":"Maritime security","kind":"self_credit"},{"t":210,"quote":"And this topic will remain a high priority when Greece assumes the presidency of the security council next month.","topic":"Greece presidency","kind":"fact"},{"t":236,"quote":"We literally sit at the intersection of the shrinking space between the east and the west.","topic":"Greece presidency","kind":"fact"},{"t":252,"quote":"Greece has developed strong strategic partnerships with key countries in the region including Israel, Egypt, Saudi Arabia, the UAE, Bahrain, and Qatar.","topic":"Greece presidency","kind":"fact"},{"t":276,"quote":"the Gaza peace plan agreed last year must be effectively implemented","topic":"Gaza conflict","kind":"fact"},{"t":284,"quote":"Hamas surrenders its arms. It can have no role, I repeat, no role in Gaza's future","topic":"Gaza conflict","kind":"fact"},{"t":356,"quote":"The US facilitated negotiations with Israel are an important step forward and should be sustained.","topic":"Lebanon security","kind":"fact"},{"t":363,"quote":"Gree strongly supports a sovereign, resilient, and united Lebanon and the government's efforts to restore the state's monopoly over arms.","topic":"Lebanon security","kind":"fact"},{"t":422,"quote":"The new Syrian authorities have taken steps in this direction.","topic":"Syria stability","kind":"fact"},{"t":438,"quote":"And this of course includes the Orthodox Christian minority which unfortunately continues to face the violence of Islamist","topic":"Syria stability","kind":"fact"},{"t":486,"quote":"Over the past three years, we have made a sustained effort to improve our relationship, rebuild trust, and keep uh channels of communication open in order to prevent the escalation of tensions that could lead to unwanted crisis.","topic":"Greece-Turkey relations","kind":"fact"},{"t":539,"quote":"the UN Convention on the Law of the Sea provides the only institutional framework to solve our only longlasting dispute concerning the delimitation of our continental shelf and our exclusive economic zones.","topic":"Greece-Turkey relations","kind":"fact"},{"t":596,"quote":"52 years 52 years have passed since Turkey illegally invaded Cyprus and continued to occupy it.","topic":"Cyprus reunification","kind":"fact"},{"t":670,"quote":"The war in Ukraine is now in its fifth year. Five years since Russia's full-scale aggression brought back war to European soil.","topic":"Cyprus reunification","kind":"fact"},{"t":716,"quote":"The nearly four-year conflict has resulted in a staggering humanitarian catastrophe.","topic":"Sudan conflict","kind":"fact"},{"t":722,"quote":"Reports of atrocious war crimes continue to emerge.","topic":"Sudan conflict","kind":"fact"},{"t":767,"quote":"our continent will be the first to suffer from a possible massive new migratory","topic":"Migration policy","kind":"fact"},{"t":795,"quote":"Greece serves as an example that sound reform oriented policies can deliver real results for people and improve their lives","topic":"Migration policy","kind":"self_credit"},{"t":818,"quote":"having lost more than 25% of its GDP","topic":"Greece economy","kind":"number"},{"t":823,"quote":"Today the economy is growing much faster than the European average","topic":"Greece economy","kind":"fact"},{"t":839,"quote":"Our public debt is declining faster than any other OECD country","topic":"Greece economy","kind":"fact"},{"t":855,"quote":"Few days ago, two leading rating agencies upgraded their outlook of the Greek economy","topic":"Greece economy","kind":"fact"},{"t":871,"quote":"today Greece's borrowing costs would be lower than that of four G7 countries","topic":"Greece economy","kind":"fact"},{"t":886,"quote":"Economic growth is vital because it expands a nation's strategic leverage. It enables a state to boler to to bolster its defense.","topic":"Greece economy","kind":"fact"},{"t":896,"quote":"A core commitment this government is proud to adhere to to modernize its infrastructure to invest in innovation all while safeguarding social cohesion.","topic":"Greece economy","kind":"self_credit"},{"t":953,"quote":"And as we prepare to assume the presidency of the Council of the European Union in the second half of 2027, we will work for a Europe that is more competitive, more secure, more capable of defending itself, and more effective in protecting its external borders.","topic":"Energy security","kind":"fact"},{"t":976,"quote":"Connectivity is the tangible face of geopolitics. The region's energy landscape is fundamentally transformed.","topic":"Energy security","kind":"fact"},{"t":1041,"quote":"More than 90% of global trade is conducted by sea.","topic":"Energy security","kind":"number"},{"t":1090,"quote":"For the first time, for the first time in the history of our species, we have created a technology that openly challenges the supremacy of the human mind as the pinnacle of our evolutionary development.","topic":"AI regulation","kind":"fact"},{"t":1134,"quote":"When the people developing the technology tell us openly that left unchecked, AI could outrun our ability to control these systems.","topic":"AI regulation","kind":"fact"},{"t":1145,"quote":"The same people admit that we only understand a tiny fraction of what goes on in these models.","topic":"AI regulation","kind":"fact"},{"t":1174,"quote":"the possibility of massive job destruction, the likelihood of unprecedented wealth creation in the hands of very few","topic":"AI regulation","kind":"fact"},{"t":1196,"quote":"The idea that big tech companies will find some voluntary arrangement to self-regulate the development of AI is naive","topic":"AI regulation","kind":"fact"},{"t":1240,"quote":"In the 1940s and the 1950s, the American government heavily regulated another technology so powerful that its creators believed it could bring about either a golden age in human flourishing or the end of the world.","topic":"AI regulation","kind":"fact"},{"t":1276,"quote":"In order for a new plane to fly, it has to undergo a myriad of rigorous tests approved by the regulator. The same is not true for a frontier artificial intelligence model.","topic":"AI regulation","kind":"fact"},{"t":1307,"quote":"Liberal capitalism has a history of reigning in market excesses, whether it was breaking a powerful monopolies or setting rules and standards to allow the market to operate with an eye on the common good.","topic":"AI regulation","kind":"fact"},{"t":1340,"quote":"It will be decided primarily here in the United States.","topic":"AI regulation","kind":"fact"}],"promises":[{"t":300,"quote":"Greece will continue to advocate for a two-state solution with Israel and Palestine living side by side in peace","topic":"Gaza conflict","kind":"promise"},{"t":381,"quote":"Therefore, we will continue to deliver concrete assistance to the country, including to the Lebanese armed forces.","topic":"Lebanon security","kind":"promise"},{"t":466,"quote":"And Greece is ready to support Libyan institutions in border protection in migration management and we remain fully committed to reaching an agreement on the limitation of our maritime zones.","topic":"Syria stability","kind":"promise"},{"t":960,"quote":"we will work for a Europe that is more competitive, more secure, more capable of defending itself, and more effective in protecting its external borders.","topic":"Energy security","kind":"promise"},{"t":1006,"quote":"Therefore, we're investing in a new generation of connectivity projects such as GREG, which will bring clean energy from Egypt to Europe, and the Great Sea Interconnector, which will connect European electricity grids with Cyprus and Israel.","topic":"Energy security","kind":"promise"}],"attacks":[{"t":599,"quote":"Turkey illegally invaded Cyprus and continued to occupy it. A flagrant violation of international law","topic":"Cyprus reunification","target":"Turkey"}],"greece":[{"t":244,"quote":"My country is a pillar of stability, connectivity and peace across the eastern Mediterranean, the Middle East and the Gulf region.","refers":["Greece","Eastern Mediterranean"],"tone":"supportive","el":"Ο ομιλητής περιγράφει τη χώρα του ως πυλώνα σταθερότητας και ειρήνης στην Ανατολική Μεσόγειο.","en":"The speaker describes their country as a pillar of stability and peace in the Eastern Mediterranean."},{"t":252,"quote":"Greece has developed strong strategic partnerships with key countries in the region including Israel, Egypt, Saudi Arabia, the UAE, Bahrain, and Qatar.","refers":["Greece","Eastern Mediterranean"],"tone":"supportive","el":"Η Ελλάδα έχει αναπτύξει ισχυρές στρατηγικές συνεργασίες με χώρες της περιοχής όπως το Ισραήλ, την Αίγυπτο και άλλες.","en":"Greece has developed strong strategic partnerships with key countries in the region including Israel, Egypt, and others."},{"t":466,"quote":"And Greece is ready to support Libyan institutions in border protection in migration management and we remain fully committed to reaching an agreement on the limitation of our maritime zones.","refers":["Greece","Eastern Mediterranean"],"tone":"conciliatory","el":"Η Ελλάδα εκφράζει την ετοιμότητά της να υποστηρίξει τη Λιβύη στη διαχείριση των συνόρων και την μετανάστευση, ενώ δεσμεύεται για τη σύναψη συμφωνίας περί του περιορισμού των θαλασσίων ζωνών.","en":"Greece expresses its readiness to support Libyan institutions in border and migration management while remaining committed to reaching an agreement on limiting maritime zones."},{"t":585,"quote":"A region which we should not forget still bears an open wound, the unresolved Cyprus issue.","refers":["Cyprus"],"tone":"conciliatory","el":"Ο ομιλητής αναφέρει ότι το Κυπριακό παραμένει ένα ανοιχτό τραύμα που δεν πρέπει να ξεχνάμε.","en":"The speaker notes that the unresolved Cyprus issue remains an open wound that must not be forgotten."},{"t":596,"quote":"52 years 52 years have passed since Turkey illegally invaded Cyprus and continued to occupy it. A flagrant violation of international law whose consequences persist to this day.","refers":["Cyprus"],"tone":"supportive","el":"Το κείμενο καταγγέλλει την παράνομη εισβολή και την κατοχή της Κύπρου από την Τουρκία ως σαφή παραβίαση του διεθνούς δικαίου.","en":"The text condemns Turkey's illegal invasion and continued occupation of Cyprus as a flagrant violation of international law."},{"t":610,"quote":"For the United Nations, Cyprus remains a litmos test of its credibility, of its ability to uphold its own resolutions and the principles of the charter.","refers":["Cyprus"],"tone":"supportive","el":"Η Κύπρος αποτελεί για τον ΟΗΕ δοκιμασία της αξιοπιστίας του και της ικανότητάς του να σέβεται τις αποφάσεις του.","en":"Cyprus remains a litmus test for the UN's credibility and its ability to uphold its own resolutions and Charter principles."},{"t":622,"quote":"And Greece fully supports the recent efforts of Secretary General Gutierrez to create the appropriate conditions for the resumption of substantive negotiations and we sincerely hope that progress can be achieved during his remaining time in office.","refers":["Cyprus"],"tone":"conciliatory","el":"Η Ελλάδα υποστηρίζει πλήρως τις προσπάθειες του Γενικού Γραμματέα για την επανέναρξη διαπραγματεύσεων για την Κύπρο.","en":"Greece fully supports recent efforts by the Secretary-General to create conditions for resuming substantive negotiations on Cyprus."},{"t":638,"quote":"And we expect we expect these efforts to continue under his successor with the same objective, the reunification of Cyprus free of occupation forces in accordance with the relevant UN Security Council The principles at stake in Cyprus are being tested elsewhere, too.","refers":["Cyprus"],"tone":"conciliatory","el":"Αναμένουμε οι προσπάθειες για την επανένωση της Κύπρου χωρίς ξένες δυνάμεις κατοχής να συνεχιστούν από τον διάδοχο του ΓΓ.","en":"We expect these efforts to continue under the successor with the same objective: the reunification of Cyprus free of occupation forces in accordance with relevant UN Security Council principles."},{"t":1006,"quote":"Therefore, we're investing in a new generation of connectivity projects such as GREG, which will bring clean energy from Egypt to Europe, and the Great Sea Interconnector, which will connect European electricity grids with Cyprus and Israel.","refers":["Cyprus","Eastern Mediterranean"],"tone":"supportive","el":"Η Ελλάδα επενδύει σε έργα διασύνδεσης ενέργειας που συνδέουν την Κύπρο και το Ισραήλ με τα ευρωπαϊκά δίκτυα.","en":"Greece is investing in connectivity projects that link Cyprus and Israel to European electricity grids."}],"said":[{"topic":"AI regulation","said":0.195,"reported":0.0505,"articles":5},{"topic":"Greece economy","said":0.104,"reported":0.0404,"articles":4},{"topic":"Energy security","said":0.1012,"reported":0.0909,"articles":9},{"topic":"Cyprus reunification","said":0.0985,"reported":0.1818,"articles":18},{"topic":"UN Security Council","said":0.0566,"reported":0.0202,"articles":2},{"topic":"Syria stability","said":0.0554,"reported":0.0505,"articles":5},{"topic":"Greece-Turkey relations","said":0.0538,"reported":0.2222,"articles":22},{"topic":"UN multilateralism","said":0.0504,"reported":0.0606,"articles":6},{"topic":"Lebanon security","said":0.0493,"reported":0.0404,"articles":4},{"topic":"Greece presidency","said":0.0481,"reported":0.0202,"articles":2},{"topic":"Maritime security","said":0.048,"reported":0.1515,"articles":15},{"topic":"Gaza conflict","said":0.0473,"reported":0.0505,"articles":5},{"topic":"Sudan conflict","said":0.0466,"reported":0.0202,"articles":2},{"topic":"Migration policy","said":0.0459,"reported":0.0,"articles":0}],"pickup":[{"outlet":"Ta Nea","date":"2026-09-24","title":"Σήμερα η ομιλία Μητσοτάκη στον ΟΗΕ","url":"https://www.tanea.gr/2026/09/24/politics/simera-i-omilia-mitsotaki-ston-oie","tone":"neutral"},{"outlet":"Proto Thema","date":"2026-09-24","title":"Μητσοτάκης στον ΟΗΕ: Η «δύσκολη γειτονιά», το μήνυμα στις αγορές και το ενεργειακό στοίχημα","url":"https://www.protothema.gr/politics/article/1883711/mitsotakis-ston-oie-i-duskoli-geitonia-to-minuma-stis-agores-kai-to-energeiako-stoihima","tone":"neutral"},{"outlet":"TVXS","date":"2026-09-24","title":"Τα των διαδρόμων / Η «επένδυση» Τσίπρα στον ΣΚΑΪ, μία απάντηση στον «μπάφο», η αριστερή μεταγραφολογία","url":"https://tvxs.gr/news/ellada/ta-ton-diadromon-i-ependysi-tsipra-ston-skai-mia-apantisi-ston-mpafo-i-aristeri-metagrafologia","tone":"critical"},{"outlet":"Efsyn","date":"2026-09-24","title":"Σήμερα η ομιλία Μητσοτάκη στον ΟΗΕ: Παρέμβαση για τα ελληνοτουρκικά και το Κυπριακό","url":"https://www.efsyn.gr/politiki/1473511/simera-i-omilia-mitsotaki-ston-oie-paremvasi-gia-ta-ellinotoyrkika-kai-to-kypriako","tone":"neutral"},{"outlet":"Efsyn","date":"2026-09-24","title":"Κυριάκος Μητσοτάκης: Ελληνοτουρκικά, κυπριακό και Τεχνητή Νοημοσύνη στο επίκεντρο της ομιλίας στον ΟΗΕ","url":"https://www.efsyn.gr/politiki/1474042/kyriakos-mitsotakis-ellinotoyrkika-kypriako-kai-tehniti-noimosyni-sto-epikentro-tis-omilias-ston-oie","tone":"neutral"},{"outlet":"Ta Nea","date":"2026-09-24","title":"Ελληνοτουρκικά, Κυπριακό, οικονομία και ΑΙ: Τι θα πει ο Κυριάκος Μητσοτάκης στη Γενική Συνέλευση του ΟΗΕ","url":"https://www.tanea.gr/2026/09/24/politics/government/ellinotourkika-kypriako-oikonomia-kai-ai-ti-tha-pei-o-kyriakos-mitsotakis-sti-geniki-syneleysi-tou-oie","tone":"neutral"},{"outlet":"Iefimerida","date":"2026-09-24","title":"Ελληνοτουρκικές σχέσεις, Κυπριακό και Τεχνητή Νοημοσύνη τα βασικά σημεία της ομιλίας Μητσοτάκη τα ξημερώματα της Παρασκευής στον ΟΗΕ","url":"https://www.iefimerida.gr/politiki/mitsotakis-omilia-oie-ellinotoyrkikes-sheseis-kypriako-ai","tone":"neutral"},{"outlet":"Naftemporiki","date":"2026-09-24","title":"Ελληνοτουρκικά, Κυπριακό και Μέση Ανατολή στο επίκεντρο της αποψινής ομιλίας του Κ. Μητσοτάκη στον ΟΗΕ","url":"https://www.naftemporiki.gr/politics/2166252/ellinotoyrkika-kypriako-kai-mesi-anatoli-sto-epikentro-tis-apopsinis-omilias-toy-k-mitsotaki-ston-oie","tone":"neutral"},{"outlet":"Newsbomb","date":"2026-09-24","title":"Μητσοτάκης: Τι θα πει στον ΟΗΕ – Να συνεχιστεί ο διάλογος με την Τουρκία χωρίς μονομερείς ενέργειες","url":"https://www.newsbomb.gr/politikh/story/1765702/mitsotakis-ti-tha-pei-ston-oie---na-synexistei-o-dialogos-me-tin-tourkia-xoris-monomereis-energeies","tone":"neutral"},{"outlet":"To Vima","date":"2026-09-24","title":"Ελληνοτουρκικα, κυπριακό και Τεχνητή Νοημοσύνη – Όσα θα πει ο Μητσοτάκης στον ΟΗΕ","url":"https://www.tovima.gr/2026/09/24/politics/ellinotourkika-kypriako-kai-i-texniti-noimosyni-osa-tha-pei-o-mitsotakis-ston-oie","tone":"neutral"},{"outlet":"In.gr","date":"2026-09-24","title":"Τι θα πει ο Κυριάκος Μητσοτάκης στη Γενική Συνέλευση του ΟΗΕ","url":"https://www.in.gr/2026/09/24/politics/epikairotita/ti-tha-pei-o-kyriakos-mitsotakis-sti-geniki-syneleysi-tou-oie","tone":"neutral"},{"outlet":"Efsyn","date":"2026-09-24","title":"ΟΗΕ: Ο Μητσοτάκης συναντήθηκε με τον Νετανιάχου – Τι συζήτησαν [εικόνες – βίντεο]","url":"https://www.efsyn.gr/politiki/1474047/oie-o-mitsotakis-synantithike-me-ton-netaniahoy-ti-syzitisan-eikones-vinteo","tone":"neutral"},{"outlet":"Flash.gr","date":"2026-09-24","title":"Μητσοτάκης - Νετανιάχου συναντήθηκαν στη Νέα Υόρκη – Στο τραπέζι ενέργεια και νέα τριμερής με Κύπρο","url":"https://www.flash.gr/mitsotakis-netaniachoy-synantithikan-sti-nea-yorki-sto-trapezi-energeia-kai-nea-trimeris-me-kypro-1082889","tone":"neutral"},{"outlet":"Ta Nea","date":"2026-09-24","title":"Συνάντηση Μητσοτάκη-Νετανιάχου: Στο επίκεντρο η αμυντική συμμαχία και η τριμερής με την Κύπρο","url":"https://www.tanea.gr/2026/09/24/politics/synantisi-mitsotaki-netaniaxou-sto-epikentro-i-amyntiki-symmaxia-kai-i-trimeris-me-tin-kypro","tone":"neutral"},{"outlet":"Avgi","date":"2026-09-24","title":"Επί τάπητος αμυντική συνεργασία και ενέργεια","url":"https://www.avgi.gr/politiki/528172_epi-tapitos-amyntiki-synergasia-kai-energeia","tone":"critical"},{"outlet":"Newsbomb","date":"2026-09-24","title":"Κυριάκος Μητσοτάκης: Παρακολουθήστε live την ομιλία του πρωθυπουργού στον ΟΗΕ","url":"https://www.newsbomb.gr/politikh/story/1765775/kyriakos-mitsotakis-parakolouthiste-live-tin-omilia-tou-prothypourgoy-ston-oie","tone":"neutral"},{"outlet":"Naftemporiki","date":"2026-09-24","title":"Live – H ομιλία του Κυριάκου Μητσοτάκη στον ΟΗΕ","url":"https://www.naftemporiki.gr/politics/2166389/live-h-omilia-toy-kyriakoy-mitsotaki-ston-oie","tone":"neutral"},{"outlet":"Flash.gr","date":"2026-09-25","title":"Μητσοτάκης στον ΟΗΕ: «Δεν αλλάζουμε τη γεωγραφία» – Το μήνυμα σε Τουρκία για το casus belli","url":"https://www.flash.gr/mitsotakis-ston-oie-den-allazoyme-ti-geografia-to-minyma-se-toyrkia-gia-to-casus-belli-1082914","tone":"neutral"},{"outlet":"To Vima","date":"2026-09-25","title":"Μητσοτάκης από ΟΗΕ: Μήνυμα διαλόγου προς την Τουρκία με «κόκκινες γραμμές»","url":"https://www.tovima.gr/2026/09/25/politics/mitsotakis-apo-oie-minyma-dialogou-pros-tin-tourkia-me-kokkines-grammes","tone":"neutral"},{"outlet":"Iefimerida","date":"2026-09-25","title":"Ελληνοτουρκικά: Γιατί χαμηλώνει τους τόνους ο Ερντογάν -Πώς διαβάζει η Αθήνα τη «στροφή» της Νέας Υόρκης","url":"https://www.iefimerida.gr/politiki/ellinotoyrkika-hamilonei-tonoys-erntogan-athina-nea-yorki","tone":"neutral"},{"outlet":"Efsyn","date":"2026-09-25","title":"Μητσοτάκης στον ΟΗΕ: Η Ελλάδα είναι γεφυροποιός, όχι κράτος ταραξίας – Ο διάλογος δεν συνυπάρχει με μονομερείς ενέργειες","url":"https://www.efsyn.gr/politiki/1474204/mitsotakis-ston-oie-i-ellada-einai-gefyropoios-ohi-kratos-taraxias-o-dialogos-den-synyparhei-me-monomereis-energeies","tone":"neutral"},{"outlet":"Proto Thema","date":"2026-09-25","title":"Μητσοτάκης: Ναι στον διάλογο με την Τουρκία, όχι στις μονομερείς ενέργειες και το casus belli - Το τετ α τετ με τον Νετανιάχου και το στοίχημα της Exxon","url":"https://www.protothema.gr/politics/article/1884371/mitsotakis-nai-ston-dialogo-me-tin-tourkia-ohi-stis-monomereis-energeies-kai-to-casus-belli-to-tet-a-tet-me-ton-neta","tone":"neutral"},{"outlet":"Newsbomb","date":"2026-09-25","title":"Ο Μητσοτάκης στον ΟΗΕ: Ήρεμα νερά με την Τουρκία, χωρίς αλλαγή γραμμής","url":"https://www.newsbomb.gr/politikh/story/1765808/o-mitsotakis-ston-oie-irema-nera-me-tin-tourkia-xoris-allagi-grammis","tone":"neutral"},{"outlet":"ThePressProject","date":"2026-09-25","title":"«Η Ελλάδα είναι γεφυροποιός, όχι κράτος ταραξίας» λέει ο Μητσοτάκης στον ΟΗΕ αφού συναντήθηκε με τον Νετανιάχου","url":"https://thepressproject.gr/i-ellada-einai-gefyropoios-ochi-kratos-taraxias-leei-o-mitsotakis-ston-oie-afou-synantithike-me-ton-netaniachou","tone":"neutral"},{"outlet":"Iefimerida","date":"2026-09-25","title":"Τα μηνύματα Μητσοτάκη στην Τουρκία από τον ΟΗΕ -«Ναι» στον διάλογο, αλλά χωρίς μονομερείς ενέργειες και απειλές πολέμου","url":"https://www.iefimerida.gr/politiki/minymata-mitsotaki-stin-toyrkia-apo-ton-oie","tone":"neutral"}],"transcript":[{"t":2,"topic":"UN Security Council","text":"The assembly will hear an address by His Excellency Kiryakos Mitsakis, Prime Minister of the Hellenic Republic. I request protocol to escort his excellency and invite him to address the Thank you. Thank you, Mr. President. U ladies and gentlemen, u uh it is u a great honor to address the general assembly for the eighth time as prime minister of Greece. And I do so at a moment of particular importance as Greece reaches the end of our second year on the UN Security Council and is again preparing to assume its presidency next month. 12 months ago, as we marked the 80th anniversary of the United Nations, we spoke of the need to reinvigorate And one year later, that need has only become much more urgent as we are living through extremely perilous times."},{"t":78,"topic":"UN multilateralism","text":"Conflicts are multiplying, tensions are deepening, and perhaps most alarmingly, we are witnessing a further erosion of restraint in international affairs. The rules and understandings that have long provided a relative degree of stability in international relations between states are increasingly being tested. Secretary General Antonio Gutierrez has steered these United Nations through this exceptionally turbulent decade with a steadfast commitment to its charter and the values it embodies. And the selection of the 10th Secretary General presents a historic opportunity for the reinvigoration of the organization when it is most needed. Ladies and gentlemen, the first step in restoring confidence in multilateralism is acknowledging where it has actually succeeded and few examples are more powerful than the United Nations Convention on the Law of the Sea with 172 parties."},{"t":146,"topic":"Maritime security","text":"UNLO provides the binding legal framework within which disputes can be managed peacefully rather than through force. And from the straight of Hermuz and the Red Sea to the strategic maritime routes are increasingly becoming arenas of geopolitical confrontation. Commercial vessels are being targeted and vital trade routes are used as instruments of pressure with grave consequences for supply chains, for energy markets, and for food security worldwide. Freedom of navigation and uninhibited passage through international straits as guaranteed by international law must be championed globally. And it is our collective responsibility to uphold these principles in practice and to safeguard commercial shipping. And as a leading maritime nation, Greece actively contributes to maritime security through the operation of the European Union diaspidas in the Red Sea."},{"t":210,"topic":"Greece presidency","text":"And this topic will remain a high priority when Greece assumes the presidency of the security council next month. We intend to place particular attention to the challenges posed by emerging technologies. Ladies and gentlemen, Greece's geography grants it the natural role of serving as a bridge between Europe and its wider neighborhood to the east and the south. We literally sit at the intersection of the shrinking space between the east and the west. My country is a pillar of stability, connectivity and peace across the eastern Mediterranean, the Middle East and the Gulf region. Greece has developed strong strategic partnerships with key countries in the region including Israel, Egypt, Saudi Arabia, the UAE, Bahrain, and Qatar. We are a bridgebuilder. We are not a troublemaker. Yet putting this vision into practice is really simple at a time of tectonic geopolitical changes."},{"t":275,"topic":"Gaza conflict","text":"In the Middle East, the Gaza peace plan agreed last year must be effectively implemented. It is of paramount concern to ensure that Hamas surrenders its arms. It can have no role, I repeat, no role in Gaza's future. At the same time, reconstruction needs to move forward with Palestinians themselves taking ownership of Gaza's future. Greece will continue to advocate for a two-state solution with Israel and Palestine living side by side in peace and However, developments in the West Bank remain a source of deep concern. Actions that are illegal under international law and undermine the viability of a future Palestinian state cannot be allowed to continue. We strongly argue that this is also to the benefit of the long-term security of Israel itself. Greece has established a durable a deep strategic partnership with Israel while at the same time maintaining strong ties with the Arab world."},{"t":339,"topic":"Lebanon security","text":"And it is precisely it is precisely the strength of this partnership that allows us to engage in an open and candid dialogue in Lebanon. There is now a real opportunity to lay the foundations for a lasting peace. The US facilitated negotiations with Israel are an important step forward and should be sustained. Gree strongly supports a sovereign, resilient, and united Lebanon and the government's efforts to restore the state's monopoly over arms. Ultimately, a stronger Lebanese state will serve both domestic security and regional stability. Therefore, we will continue to deliver concrete assistance to the country, including to the Lebanese armed forces. With the UNIFIL's mandate ending, joint action is crucial to avoid a security vacuum and maintain an effective international and European Syria is another key player in the region."},{"t":406,"topic":"Syria stability","text":"Lasting stability in the Middle East requires a stable Syria. A Syria that is inclusive. A Syria that is free from foreign interference and regional rivalries. A Syria where every citizen can and should feel secure. The new Syrian authorities have taken steps in this direction. Yet further concrete progress must be demonstrated particularly when it comes to protecting the rights and security of all religious and ethnic communities. And this of course includes the Orthodox Christian minority which unfortunately continues to face the violence of Islamist The search for stability extends to Libya, a neighbor with whom we share many common interests. We praise all reunification efforts. Sustainable Libya free from foreign interference would benefit not only the Libyan people but our entire region. And Greece is ready to support Libyan institutions in border protection in migration management and we remain fully committed to reaching an agreement on the limitation of our maritime zones."},{"t":481,"topic":"Greece-Turkey relations","text":"Ladies and gentlemen, let me now turn to our relations with our neighbor Turkey. Over the past three years, we have made a sustained effort to improve our relationship, rebuild trust, and keep uh channels of communication open in order to prevent the escalation of tensions that could lead to unwanted crisis. It is a delicate relationship. It's a relationship that carries the weight of history. And indeed, given broader and regional challenges, the situation calls, urgently calls for a common understanding on how we move forward. An understanding grounded in full respect for international law and the principles of good neighborly relations. After all, as I've said repeatedly, we cannot change our geography. We are destined to live side by side. And I re repeat that the UN Convention on the Law of the Sea provides the only institutional framework to solve our only longlasting dispute concerning the delimitation of our continental shelf and our exclusive economic zones."},{"t":554,"topic":"Cyprus reunification","text":"Dialogue is essential for peace and prosperity, but meaningful dialogue cannot coexist with unilateral actions that challenge the international legal order. nor can meaningful progress be made when faced with threats of war in response to the exercise of lawful rights according to international law. Such actions do not resolve differences. They end up by only deepening them and they risk undermining the stability of our wider region. A region which we should not forget still bears an open wound, the unresolved Cyprus issue. 52 years 52 years have passed since Turkey illegally invaded Cyprus and continued to occupy it. A flagrant violation of international law whose consequences persist to this day. For the United Nations, Cyprus remains a litmos test of its credibility, of its ability to uphold its own resolutions and the principles of the charter."},{"t":622,"topic":"Cyprus reunification","text":"And Greece fully supports the recent efforts of Secretary General Gutierrez to create the appropriate conditions for the resumption of substantive negotiations and we sincerely hope that progress can be achieved during his remaining time in office. And we expect we expect these efforts to continue under his successor with the same objective, the reunification of Cyprus free of occupation forces in accordance with the relevant UN Security Council The principles at stake in Cyprus are being tested elsewhere, too. Today, two other major conflicts continue to challenge our ability to defend the values upon which this organization was founded. The war in Ukraine is now in its fifth year. Five years since Russia's full-scale aggression brought back war to European soil. The Ukrainian people have shown extraordinary courage defending their freedom and Greece continuously stands with them."},{"t":686,"topic":"Sudan conflict","text":"We strongly strongly condemn attacks against civilians and civilian infrastructure. Diplomacy must now deliver an immediate ceasefire and a lasting peace anchored in the principles of the United Nations charter. Ukraine must have a decisive say in its own future and Europe cannot be absent from these negotiations. Against this backdrop, another devastating war demands our urgent attention in Sudan. The nearly four-year conflict has resulted in a staggering humanitarian catastrophe. Reports of atrocious war crimes continue to emerge. While the conflict is fueling instability way beyond far beyond Sudan's borders, we should not permit this tragedy to endure. Foreign interference must also cease with no impunity for war crimes. Ultimately, the way forward lies in a credible Sudaneseled political process that reflects the aspirations of the citizen Suzanne."},{"t":749,"topic":"Migration policy","text":"The European Union ought to leverage its capacity to play a more active role in supporting that process and assisting in bringing this destructive conflict to an end. After all, it has real skill in the game. Should the devastating war continue, our continent will be the first to suffer from a possible massive new migratory Ladies and gentlemen, Greece's confidence abroad rests on a profound transformation at home at a time when the effectiveness of governments all over the world is being challenged by populists and extremists and public trust is being eroded in the echo chambers of social media. Greece serves as an example that sound reform oriented policies can deliver real results for people and improve their lives. Of course, significant challenges remain, but the progress Greece has made is impossible to overlook."},{"t":812,"topic":"Greece economy","text":"7 years ago, my country was still emerging from the most painful economic crisis in its modern history, having lost more than 25% of its GDP. Today the economy is growing much faster than the European average while Greece is attracting significant foreign direct Public finances are solid and our fiscal performance has become a positive example in Europe. Our public debt is declining faster than any other OECD country. Structural reforms and the digitalization of the state which has helped reduce bureaucracy have transformed the public administration and restored trust among investors. Few days ago, two leading rating agencies upgraded their outlook of the Greek economy. And at a time of great turbulence in the global bond markets, this says a lot about the progress that Greece has made. And not many people would have bet a few years ago that today Greece's borrowing costs would be lower than that of four G7 countries."},{"t":877,"topic":"Greece economy","text":"This transformation was not easy. It was made possible by the hard work, the resilience, and the determination of the Greek people. Economic growth is vital because it expands a nation's strategic leverage. It enables a state to boler to to bolster its defense. A core commitment this government is proud to adhere to to modernize its infrastructure to invest in innovation all while safeguarding social cohesion. Economic resilience is therefore inherently intertwined with robust institutions and credible deterrent Greece's ambition is to serve as a nexus through which lasting partnerships are being forged. And I was reminded of this vision earlier this year when I welcomed President Emanuel Mcron at the Roman Agora in Athens to discuss Europe's place in a shifting geopolitical landscape. The setting was particularly meaningful. The agora was a place where commerce, law, and public life once There we reflected on how Europe can transform the crisis into an opportunity for its strategic autonomy and improve its competitiveness."},{"t":953,"topic":"Energy security","text":"And as we prepare to assume the presidency of the Council of the European Union in the second half of 2027, we will work for a Europe that is more competitive, more secure, more capable of defending itself, and more effective in protecting its external borders. Another lesson, however, is becoming increasingly clear. Connectivity is the tangible face of geopolitics. The region's energy landscape is fundamentally transformed. Electricity grids, energy, and digital corridors, ports, and shipping routes are levers of power. Geography matters and our ambition is to translate our unique position into stronger links between Europe, the Middle East, the Gulf, and North Africa. Therefore, we're investing in a new generation of connectivity projects such as GREG, which will bring clean energy from Egypt to Europe, and the Great Sea Interconnector, which will connect European electricity grids with Cyprus and Israel."},{"t":1023,"topic":"Energy security","text":"At the same time, we leverage our unique geographic positions to become a provider of energy security to our northern neighbors. And as the prime minister of a leading shipping nation, it is worth remembering a stark fact. More than 90% of global trade is conducted by sea. If we systematically threaten the freedom of navigation and do not protect vital sea routes, the global economy risks coming to a grinding halt. And this is something that should be of great interest to every single country represented in this great assembly. Ladies and gentlemen, I would like to conclude with a few thoughts on the topic of artificial intelligence. One of my favorite bands when I was growing up was Talking Heads. And little did I know that the the time that David Burn iconic song We Are on a Road to Nowhere would ring so precient four decades later."},{"t":1090,"topic":"AI regulation","text":"For the first time, for the first time in the history of our species, we have created a technology that openly challenges the supremacy of the human mind as the pinnacle of our evolutionary development. I will not dwell on the positive transformational potential of this revolutionary technology whether in disease eradication, productivity enhancement or fighting climate change. However, it is simply impossible to ignore the fact that at present the risks of an unchecked and unregulated advance in artificial intelligence could greatly outweigh its potential benefits. When the people developing the technology tell us openly that left unchecked, AI could outrun our ability to control these systems. The same people admit that we only understand a tiny fraction of what goes on in these models."},{"t":1153,"topic":"AI regulation","text":"Alarm bells should ring very loudly for all of us. In simple words, the AI bosses are telling us that they have no idea on how recursive the ability of AI to constantly create better versions of itself, actually Add to that the possibility of massive job destruction, the likelihood of unprecedented wealth creation in the hands of very few, and the impact that AI may have on the very nature of human especially for our kids, and you have all the ingredients of an unprecedented political and social upheaval. The idea that big tech companies will find some voluntary arrangement to self-regulate the development of AI is naive. It flies in the face of everything we know about the history of capitalism. The prize for the winners is simply too great to believe that benign consideration for the well-being of humanity without way the relentless drive of capital to constantly seek better returns."},{"t":1227,"topic":"AI regulation","text":"And given that the leading AI models are being developed here in the United States, this is primarily an issue for the US government to address. Unfortunately, there are precedents from which we draw lessons. In the 1940s and the 1950s, the American government heavily regulated another technology so powerful that its creators believed it could bring about either a golden age in human flourishing or the end of the world. That technology was The same needs to happen now and it needs to happen fast. AI companies need to be licensed based on specific requirements. adherence to human values, transparency, and most importantly, In order for a new plane to fly, it has to undergo a myriad of rigorous tests approved by the regulator. The same is not true for a frontier artificial intelligence model."},{"t":1290,"topic":"AI regulation","text":"At the same time, I take the call by leading AI executives for a voluntary pause in the development of their models very seriously, but only, I repeat, only as a temporary measure to buy time for a powerful regulatory authority to be set up. Liberal capitalism has a history of reigning in market excesses, whether it was breaking a powerful monopolies or setting rules and standards to allow the market to operate with an eye on the common good. And the same needs to happen now. And as much as the cooperation of China and the rest of the world is necessary to address this huge challenge, the fate of artificial intelligence and the impact it will have on humanity as a whole will not be decided in Brussels, in Tokyo or Brazilia. It will be decided primarily here in the United States. With great power comes great And let us hope that our host country will rise to the occasion."},{"t":1353,"topic":null,"text":"Thank you very much. &gt;&gt; On behalf of the assembly, I wish to thank the prime minister of the Hellenic"}],"compare":[{"topic":"Artificial Intelligence","share":0.195,"mean":0.0497,"rank":10,"others":83},{"topic":"UN & its reform","share":0.107,"mean":0.2053,"rank":141,"others":170},{"topic":"Global Economy","share":0.1012,"mean":0.0141,"rank":8,"others":31},{"topic":"Cyprus","share":0.0985,"mean":0.003,"rank":2,"others":2},{"topic":"Syria","share":0.0554,"mean":0.0032,"rank":6,"others":7},{"topic":"Turkey","share":0.0538,"mean":0.0002,"rank":1,"others":1},{"topic":"Lebanon","share":0.0493,"mean":0.0031,"rank":6,"others":6},{"topic":"Maritime Security","share":0.048,"mean":0.0045,"rank":9,"others":9}]};
